import React, { useState } from 'react';
import { Calendar, Filter, Download, ChevronDown, AlertCircle, Hash, User, Map, ListFilter } from 'lucide-react';

const CollectionSchedule = () => {
  const [day, setDay] = useState('22');
  const [month, setMonth] = useState('MARCH');
  const [year, setYear] = useState('2026');

  // NEW STATE: Toggle between 'SINGLE_DAY' and 'FULL_MONTH' view
  const [viewScope, setViewScope] = useState('SINGLE_DAY'); 

  const scheduleLogs = [
    { id: 'SCH-1092', date: '22 MAR', time: '08:45', zone: 'NORTH_SEC', area: 'Hillside Drive', code: 'HSD-44', worker: 'RAVI_K', bins: '401, 405, 409', report: 'SENSOR_ERR' },
    { id: 'SCH-1104', date: '22 MAR', time: '13:20', zone: 'CENTRAL_HUB', area: 'Main Square', code: 'MSQ-01', worker: 'SITA_M', bins: '101, 102', report: null },
    { id: 'SCH-0988', date: '15 MAR', time: '10:00', zone: 'WEST_WING', area: 'Industrial Ave', code: 'IND-09', worker: 'JOHN_D', bins: '990', report: null },
  ];

  return (
    <div className="w-full h-full flex flex-col gap-6 font-black italic uppercase tracking-tighter overflow-hidden">

      {/* 🛠️ THE MECHANICAL SELECTOR BAR */}
      <div className="flex flex-col lg:flex-row gap-4">

        {/* DATE ENGINE (PINK & YELLOW) - REMAINS UNTOUCHED */}
        <div className="relative flex-grow">
          <div className="absolute inset-0 bg-[#47510B] translate-x-1.5 translate-y-1.5 rounded-2xl" />
          <div className="relative bg-[#FFB6A9] border-[6px] border-[#47510B] rounded-2xl p-4 flex items-center gap-4">
            <div className="bg-[#47510B] p-3 rounded-xl text-[#FFF24D]"><Calendar size={24} strokeWidth={3} /></div>

            <div className="flex gap-2 flex-grow">
              {/* Day Drum */}
              <div className="flex-1 group relative">
                <select 
                  value={day} 
                  disabled={viewScope === 'FULL_MONTH'}
                  onChange={(e) => {setDay(e.target.value); setViewScope('SINGLE_DAY');}} 
                  className={`w-full appearance-none border-[4px] border-[#47510B] px-4 py-2 rounded-xl text-xl text-[#47510B] outline-none cursor-pointer transition-all ${viewScope === 'FULL_MONTH' ? 'bg-white/50 opacity-30 italic' : 'bg-[#FFF24D]'}`}
                >
                  {[...Array(31)].map((_, i) => <option key={i+1} value={i+1}>{String(i+1).padStart(2, '0')}</option>)}
                </select>
                <ChevronDown className="absolute right-3 top-3 text-[#47510B] pointer-events-none" size={16} />
              </div>

              {/* Month Drum */}
              <div className="flex-[2] group relative">
                <select value={month} onChange={(e) => setMonth(e.target.value)} className="w-full appearance-none bg-[#FFF24D] border-[4px] border-[#47510B] px-4 py-2 rounded-xl text-xl text-[#47510B] outline-none cursor-pointer">
                  {['JANUARY', 'FEBRUARY', 'MARCH', 'APRIL', 'MAY', 'JUNE', 'JULY', 'AUGUST', 'SEPTEMBER', 'OCTOBER', 'NOVEMBER', 'DECEMBER'].map(m => <option key={m} value={m}>{m}</option>)}
                </select>
                <ChevronDown className="absolute right-3 top-3 text-[#47510B] pointer-events-none" size={16} />
              </div>

              {/* Year Drum */}
              <div className="flex-1 group relative">
                <select value={year} onChange={(e) => setYear(e.target.value)} className="w-full appearance-none bg-[#FFF24D] border-[4px] border-[#47510B] px-4 py-2 rounded-xl text-xl text-[#47510B] outline-none cursor-pointer">
                  {['2024', '2025', '2026', '2027'].map(y => <option key={y} value={y}>{y}</option>)}
                </select>
                <ChevronDown className="absolute right-3 top-3 text-[#47510B] pointer-events-none" size={16} />
              </div>
            </div>
          </div>
        </div>

        {/* 📋 THE MONTHLY VIEW TOGGLE (BLUE LINEN) */}
        <button 
          onClick={() => setViewScope(viewScope === 'SINGLE_DAY' ? 'FULL_MONTH' : 'SINGLE_DAY')}
          className="relative group transition-transform active:scale-95 lg:w-80"
        >
          <div className="absolute inset-0 bg-[#47510B] translate-x-1.5 translate-y-1.5 rounded-2xl" />
          <div className={`relative h-full border-[6px] border-[#47510B] rounded-2xl px-6 py-4 flex flex-col items-center justify-center leading-none transition-all ${viewScope === 'FULL_MONTH' ? 'bg-[#FFF24D]' : 'bg-[#A1AED1]'}`}>
            <div className="flex items-center gap-3">
               <ListFilter size={20} className="text-[#47510B]" />
               <span className="text-sm">VIEW_ENTIRE_MONTH</span>
            </div>
            {viewScope === 'FULL_MONTH' && <span className="text-[10px] mt-1 text-[#AB1717]">FILTER_ACTIVE: {month}</span>}
          </div>
        </button>
      </div>

      {/* 🌊 MAIN MANIFEST AREA (DYNAMIC LIST) */}
      <div className="flex-grow overflow-y-auto pr-2 custom-scrollbar pb-20">

        <div className="flex flex-col gap-4">
          {/* HEADER LABELS */}
          <div className="grid grid-cols-12 px-8 py-2 text-[10px] text-[#47510B] opacity-50 tracking-[0.3em]">
            <div className="col-span-1">DATE/TIME</div>
            <div className="col-span-2">UNIT_ID</div>
            <div className="col-span-4">ZONE_AREA_IDENTIFIER</div>
            <div className="col-span-2">OPERATOR</div>
            <div className="col-span-2">BIN_NODES</div>
            <div className="col-span-1 text-right">REPORT</div>
          </div>

          {/* This list will now display either the filtered day OR the whole month based on the toggle */}
          {scheduleLogs.map((log) => (
            <div key={log.id} className="relative group">
              <div className="absolute inset-0 bg-[#47510B] translate-x-1 translate-y-1 rounded-2xl" />
              <div className="relative bg-white border-[4px] border-[#47510B] rounded-2xl p-6 grid grid-cols-12 items-center group-hover:bg-[#FDFAD8] transition-colors">

                {/* Date & Time Column */}
                <div className="col-span-1 leading-none">
                  <p className="text-[10px] font-black opacity-40 mb-1">{log.date}</p>
                  <div className="text-2xl text-[#47510B] font-[1000]">{log.time}</div>
                </div>

                {/* Unit ID */}
                <div className="col-span-2">
                  <span className="bg-[#A1AED1] px-3 py-1 rounded-lg border-2 border-[#47510B] text-[10px]">{log.id}</span>
                </div>

                {/* Zone & Area */}
                <div className="col-span-4">
                  <p className="text-[10px] text-[#AB1717] leading-none mb-1">{log.zone} // {log.code}</p>
                  <h3 className="text-xl text-[#47510B] leading-none">{log.area}</h3>
                </div>

                {/* Worker */}
                <div className="col-span-2 flex items-center gap-2">
                  <div className="w-8 h-8 bg-[#47510B] rounded-lg flex items-center justify-center text-[#FFF24D] shadow-[2px_2px_0_0_#47510B]"><User size={16} /></div>
                  <span className="text-xs">{log.worker}</span>
                </div>

                {/* Bins */}
                <div className="col-span-2 flex items-center gap-2">
                   <Hash size={14} className="text-[#A1AED1]" />
                   <span className="text-[10px] font-mono opacity-60 truncate w-32">{log.bins}</span>
                </div>

                {/* Report Alert */}
                <div className="col-span-1 flex justify-end">
                  {log.report ? (
                    <div className="w-10 h-10 bg-[#AB1717] rounded-full flex items-center justify-center text-white border-2 border-[#47510B] animate-pulse cursor-help" title={log.report}>
                      <AlertCircle size={20} />
                    </div>
                  ) : (
                    <div className="w-2 h-2 rounded-full bg-[#CAD23C]" />
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* 🧭 STATUS LINE */}
      <div className="bg-[#47510B] p-4 rounded-full flex justify-between items-center border-[4px] border-white shadow-[8px_8px_0_0_#A1AED1]">
         <div className="flex gap-10 ml-6">
            <span className="text-[#FFF24D] text-[10px] uppercase italic">
              SCOPE: {viewScope === 'SINGLE_DAY' ? `DAY_VIEW (${day})` : `MONTH_VIEW (${month})`}
            </span>
            <span className="text-[#A1AED1] text-[10px] uppercase italic">
              TOTAL_RECORDS: {scheduleLogs.length}
            </span>
         </div>
         <button className="bg-[#FFF24D] border-[2px] border-[#47510B] px-6 py-1 rounded-full text-[10px] font-black shadow-[3px_3px_0_0_#47510B] active:translate-y-1 active:shadow-none transition-all mr-2">
            DOWNLOAD_VISIBLE_MANIFEST.CSV
         </button>
      </div>

    </div>
  );
};

export default CollectionSchedule;
